parameters.jsCode:
// Normalização da resposta da OpenAI para o contrato comum
const raw = $input.item.json;
let parsedContent = {};
try {
  parsedContent = JSON.parse(raw.choices[0].message.content);
} catch (e) {
  throw new Error('Falha ao processar resposta JSON da OpenAI: ' + e.message);
}

return {
  json: {
    contractVersion: '1.0',
    requestId: parsedContent.requestId || 'req-openai',
    provider: 'openai',
    model: 'gpt-4o-mini',
    promptVersion: 'match-advisor-v1',
    suggestions: parsedContent.suggestions || []
  }
};
